ratings  = {"Technical depth": 4, "Problem finding": 3,
            "Customer empathy": 4, "Product judgment": 3,
            "Ownership": 4}
evidence = {"Technical depth": 3,   # shipped projects,
            "Problem finding": 0,   # stories, feedback
            "Customer empathy": 1,
            "Product judgment": 0, "Ownership": 2}

def honest(score, proofs):
    # no evidence caps you at 2, one piece at 3
    cap = 2 if proofs == 0 else 3 if proofs == 1 else 5
    return min(score, cap)

fixed = {a: honest(s, evidence[a]) for a, s in ratings.items()}
target = 3
gaps = sorted((target - s, a) for a, s in fixed.items()
              if s < target)
print(fixed)
print('Work on:', [a for _, a in gaps])
